script:
$ErrorActionPreference = "Stop"
[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
Import-Module -Name $env:XINGMANG_UPDATE_SECURITY_MODULE -Force -ErrorAction Stop
Import-Module -Name $env:XINGMANG_UPDATE_UTILITY_MODULE -Force -ErrorAction Stop
$signature = Microsoft.PowerShell.Security\Get-AuthenticodeSignature -LiteralPath $env:XINGMANG_UPDATE_SIGNATURE_TARGET -ErrorAction Stop
if ($null -eq $signature) { throw "Get-AuthenticodeSignature did not return a result" }
if ($null -eq $signature.SignerCertificate) { throw "The update installer has no signer certificate" }
[pscustomobject]@{
  Status = [string]$signature.Status
  Path = [string]$signature.Path
  Subject = [string]$signature.SignerCertificate.Subject
} | Microsoft.PowerShell.Utility\ConvertTo-Json -Compress

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
Import-Module -Name 'Microsoft.PowerShell.Utility', 'Appx' -ErrorAction SilentlyContinue
$packages = @(Get-AppxPackage -Name 'Microsoft.DesktopAppInstaller' -ErrorAction Stop | Sort-Object Version -Descending)
if ($packages.Count -eq 0) {
  try {
    $packages = @(Get-AppxPackage -AllUsers -Name 'Microsoft.DesktopAppInstaller' -ErrorAction Stop | Sort-Object Version -Descending)
  } catch {
    $packages = @()
  }
}
if ($packages.Count -gt 0) {
  $package = $packages[0]
  [pscustomobject]@{
    name = [string]$package.Name
    packageFamilyName = [string]$package.PackageFamilyName
    installLocation = [string]$package.InstallLocation
  } | ConvertTo-Json -Compress
}

$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
Import-Module -Name 'Microsoft.PowerShell.Utility' -ErrorAction SilentlyContinue
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$archive = [System.IO.Compression.ZipFile]::OpenRead('C:\xmprobe\fake.msix')
try {
  $manifestEntry = $archive.Entries | Where-Object { $_.FullName -ieq 'AppxManifest.xml' } | Select-Object -First 1
  $signatureEntry = $archive.Entries | Where-Object { $_.FullName -ieq 'AppxSignature.p7x' } | Select-Object -First 1
  if ($null -eq $manifestEntry) { throw 'MSIX 中缺少 AppxManifest.xml' }
  if ($manifestEntry.Length -le 0 -or $manifestEntry.Length -gt 1048576) { throw 'AppxManifest.xml 大小无效或超过 1 MiB 安全上限' }
  $stream = $manifestEntry.Open()
  try {
    $settings = [System.Xml.XmlReaderSettings]::new()
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    $settings.XmlResolver = $null
    $settings.MaxCharactersInDocument = 1048576
    $reader = [System.Xml.XmlReader]::Create($stream, $settings)
    try {
      $manifest = [System.Xml.XmlDocument]::new()
      $manifest.XmlResolver = $null
      $manifest.Load($reader)
    } finally { $reader.Dispose() }
  } finally { $stream.Dispose() }
  $identity = $manifest.SelectSingleNode('/*[local-name()="Package"]/*[local-name()="Identity"]')
  if ($null -eq $identity) { throw 'AppxManifest.xml 中缺少 Package/Identity' }
  [pscustomobject]@{
    name = [string]$identity.GetAttribute('Name')
    version = [string]$identity.GetAttribute('Version')
    architecture = [string]$identity.GetAttribute('ProcessorArchitecture')
    publisher = [string]$identity.GetAttribute('Publisher')
    hasSignature = ($null -ne $signatureEntry)
  } | ConvertTo-Json -Compress
} finally { $archive.Dispose() }

$ErrorActionPreference = 'Stop'
$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
$originalSid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
if ($originalSid -notmatch '^S-1-[0-9-]+$') { exit 2225 }
$installer = '$ErrorActionPreference = ''Stop''
$ProgressPreference = ''SilentlyContinue''
$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
$env:PSModulePath = Join-Path $PSHOME ''Modules''
$identity = [System.Security.Principal.WindowsIdentity]::GetCurrent()
if ($identity.User.Value -ne ''__XINGMANG_ORIGINAL_USER_SID__'') { exit 2225 }
$principal = [System.Security.Principal.WindowsPrincipal]::new($identity)
if (-not $principal.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)) { exit 740 }
$cache = $null; $payload = $null; $source = $null; $held = $null; $created = $false
$result = 1603
try {
  $root = [Environment]::GetFolderPath([Environment+SpecialFolder]::ProgramFiles)
  if (-not [IO.Path]::IsPathRooted($root)) { throw ''Invalid protected installation root'' }
  $cache = Join-Path $root (''Xingmang-Codex-Install-'' + [Guid]::NewGuid().ToString(''N''))
  $acl = [System.Security.AccessControl.DirectorySecurity]::new()
  $acl.SetAccessRuleProtection($true, $false)
  $administrators = [System.Security.Principal.SecurityIdentifier]::new(''S-1-5-32-544'')
  $acl.SetOwner($administrators)
  foreach ($sid in @(''S-1-5-18'', ''S-1-5-32-544'')) {
    $rule = [System.Security.AccessControl.FileSystemAccessRule]::new([System.Security.Principal.SecurityIdentifier]::new($sid), [System.Security.AccessControl.FileSystemRights]::FullControl, [System.Security.AccessControl.InheritanceFlags]::ContainerInherit -bor [System.Security.AccessControl.InheritanceFlags]::ObjectInherit, [System.Security.AccessControl.PropagationFlags]::None, [System.Security.AccessControl.AccessControlType]::Allow)
    $acl.AddAccessRule($rule)
  }
  [void][System.IO.Directory]::CreateDirectory($cache, $acl)
  $created = $true
  $payload = Join-Path $cache ''Codex.msix''
  $source = [System.IO.File]::Open(''C:\xmprobe\fake.msix'', [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
  if ($source.Length -le 0 -or $source.Length -gt 1572864000 -or $source.Length -ne 4096) { $result = 13; throw ''MSIX size mismatch'' }
  $held = [System.IO.File]::Open($payload, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)
  $source.CopyTo($held); $source.Dispose(); $source = $null; $held.Flush(); $held.Dispose()
  $payloadAcl = [System.IO.File]::GetAccessControl($payload)
  $payloadAcl.SetOwner($administrators)
  [System.IO.File]::SetAccessControl($payload, $payloadAcl)
  $held = [System.IO.File]::Open($payload, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
  $sha = [System.Security.Cryptography.SHA256]::Create()
  try { $actualHash = [Convert]::ToBase64String($sha.ComputeHash($held)) } finally { $sha.Dispose() }
  if ($actualHash -cne ''AQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQE='') { $result = 13 } else {
    Import-Module -Name (Join-Path $PSHOME ''Modules\Appx\Appx.psd1'') -ErrorAction Stop
    Add-AppxPackage -Path $payload -ForceApplicationShutdown -ErrorAction Stop
    $result = 0
  }
} catch { if ($result -ne 13) { $result = 1603 } } finally {
  if ($null -ne $source) { $source.Dispose() }
  if ($null -ne $held) { $held.Dispose() }
  if ($null -ne $payload) { try { [System.IO.File]::Delete($payload) } catch {} }
  if ($created) { try { [System.IO.Directory]::Delete($cache, $false) } catch {} }
}
exit $result'
$installer = $installer.Replace('__XINGMANG_ORIGINAL_USER_SID__', $originalSid)
$encoded = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($installer))
$arguments = "-NoLogo -NoProfile -NonInteractive -EncodedCommand $encoded"
try {
  $process = Start-Process -FilePath 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe' -ArgumentList $arguments -Verb RunAs -WindowStyle Hidden -WorkingDirectory $PSHOME -Wait -PassThru
  if ($null -eq $process) { exit 1603 }
  exit $process.ExitCode
} catch {
  $failure = $_.Exception
  while ($null -ne $failure) {
    if ($failure.NativeErrorCode -eq 1223 -or $failure.HResult -eq -2147023673) { exit 1223 }
    $failure = $failure.InnerException
  }
  throw
}

$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
Import-Module -Name ($PSHOME + '\Modules\Microsoft.PowerShell.Security\Microsoft.PowerShell.Security.psd1') -Force -ErrorAction Stop; Import-Module -Name ($PSHOME + '\Modules\Microsoft.PowerShell.Utility\Microsoft.PowerShell.Utility.psd1') -Force -ErrorAction Stop
Add-Type -AssemblyName System.IO.Compression.FileSystem
$packagePath = 'C:\xmprobe\fake.msix'
$archive = [System.IO.Compression.ZipFile]::OpenRead($packagePath)
try {
  $entries = @($archive.Entries | Where-Object { $_.FullName -ieq 'AppxManifest.xml' })
  if ($entries.Count -ne 1 -or $entries[0].Length -le 0 -or $entries[0].Length -gt 524288) { throw 'AppxManifest.xml missing or oversized' }
  $settings = [System.Xml.XmlReaderSettings]::new()
  $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
  $settings.XmlResolver = $null
  $settings.MaxCharactersInDocument = 524288
  $stream = $entries[0].Open()
  try {
    $reader = [System.Xml.XmlReader]::Create($stream, $settings)
    try {
      $manifest = [System.Xml.XmlDocument]::new()
      $manifest.XmlResolver = $null
      $manifest.Load($reader)
    } finally { $reader.Dispose() }
  } finally { $stream.Dispose() }
  $identity = $manifest.SelectSingleNode('/*[local-name()="Package"]/*[local-name()="Identity"]')
  if ($null -eq $identity) { throw 'Package/Identity missing' }
  $publisher = [string]$identity.GetAttribute('Publisher')
  $publisherCanonical = [System.Security.Cryptography.X509Certificates.X500DistinguishedName]::new($publisher).Decode([System.Security.Cryptography.X509Certificates.X500DistinguishedNameFlags]::UseCommas)
  $hasSignature = $null -ne ($archive.Entries | Where-Object { $_.FullName -ieq 'AppxSignature.p7x' } | Select-Object -First 1)
} finally { $archive.Dispose() }
$signature = Get-AuthenticodeSignature -LiteralPath $packagePath
$signer = $signature.SignerCertificate
[pscustomobject]@{
  name = [string]$identity.GetAttribute('Name')
  version = [string]$identity.GetAttribute('Version')
  architecture = [string]$identity.GetAttribute('ProcessorArchitecture')
  publisher = $publisher
  publisherCanonical = [string]$publisherCanonical
  hasSignature = [bool]$hasSignature
  signatureStatus = [string]$signature.Status
  signerName = if ($signer) { [string]$signer.GetNameInfo([System.Security.Cryptography.X509Certificates.X509NameType]::SimpleName, $false) } else { '' }
  signerSubject = if ($signer) { [string]$signer.SubjectName.Decode([System.Security.Cryptography.X509Certificates.X500DistinguishedNameFlags]::UseCommas) } else { '' }
} | ConvertTo-Json -Compress

$ErrorActionPreference='Stop'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
Import-Module -Name 'Microsoft.PowerShell.Utility' -ErrorAction SilentlyContinue
$manifestPath=[Text.Encoding]::Unicode.GetString([Convert]::FromBase64String('QwA6AFwAeABtAHAAcgBvAGIAZQBcAEEAcABwAHgATQBhAG4AaQBmAGUAcwB0AC4AeABtAGwA'))
if(([IO.File]::GetAttributes($manifestPath) -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw 'manifest-reparse-point'}
$stream=[IO.File]::Open($manifestPath,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
try {
  if($stream.Length -le 0 -or $stream.Length -gt 1048576){throw 'manifest-size-limit'}
  $settings=[Xml.XmlReaderSettings]::new()
  $settings.DtdProcessing=[Xml.DtdProcessing]::Prohibit
  $settings.XmlResolver=$null
  $settings.MaxCharactersInDocument=1048576
  $reader=[Xml.XmlReader]::Create($stream,$settings)
  try {
    $manifest=[Xml.XmlDocument]::new()
    $manifest.XmlResolver=$null
    $manifest.Load($reader)
  } finally {$reader.Dispose()}
} finally {$stream.Dispose()}
$namespaces=[Xml.XmlNamespaceManager]::new($manifest.NameTable)
$namespaces.AddNamespace('p','http://schemas.microsoft.com/appx/manifest/foundation/windows10')
$namespaces.AddNamespace('d6','http://schemas.microsoft.com/appx/manifest/desktop/windows10/6')
$namespaces.AddNamespace('v','http://schemas.microsoft.com/appx/manifest/virtualization/windows10')
$identity=$manifest.SelectSingleNode('/p:Package/p:Identity',$namespaces)
if($null -eq $identity -or $identity.GetAttribute('Name') -cne 'Claude' -or $identity.GetAttribute('Version') -cne '1.0.0.0' -or $identity.GetAttribute('ProcessorArchitecture') -ine 'x64'){throw 'manifest-identity-mismatch'}
$globalNodes=$manifest.SelectNodes('/p:Package/p:Properties/d6:FileSystemWriteVirtualization',$namespaces)
if($globalNodes.Count -gt 1){throw 'ambiguous-virtualization'}
$globalMode='enabled'
if($globalNodes.Count -eq 1){$globalMode=$globalNodes[0].InnerText.Trim().ToLowerInvariant()}
if($globalMode -notin @('enabled','disabled')){throw 'unsupported-virtualization'}
$excluded=@($manifest.SelectNodes('/p:Package/p:Properties/v:FileSystemWriteVirtualization/v:ExcludedDirectories/v:ExcludedDirectory',$namespaces) | ForEach-Object {$_.InnerText})
if($excluded.Count -gt 512){throw 'manifest-exclusions-limit'}
@{globalMode=$globalMode;excludedDirectories=$excluded} | ConvertTo-Json -Depth 3 -Compress

$ErrorActionPreference='Stop'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
Import-Module -Name 'Microsoft.PowerShell.Utility' -ErrorAction SilentlyContinue
function Read-Hive($hive) {
  $root=[Microsoft.Win32.RegistryKey]::OpenBaseKey($hive,[Microsoft.Win32.RegistryView]::Registry64)
  $key=$null
  try {
    $key=$root.OpenSubKey('SOFTWARE\Policies\Claude',$false)
    if($null -eq $key){return}
    foreach($name in $key.GetValueNames()) {
      [pscustomobject]@{name=$name;kind=$key.GetValueKind($name).ToString()}
    }
  } finally {if($null -ne $key){$key.Dispose()};$root.Dispose()}
}
@{machine=@(Read-Hive ([Microsoft.Win32.RegistryHive]::LocalMachine));user=@(Read-Hive ([Microsoft.Win32.RegistryHive]::CurrentUser))} | ConvertTo-Json -Depth 4 -Compress

$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
Import-Module -Name 'Microsoft.PowerShell.Utility', 'CimCmdlets' -ErrorAction SilentlyContinue
$ErrorActionPreference = "SilentlyContinue"
$root = [string]$env:XINGMANG_CLI_PROCESS_ROOT
if (-not $root) { '[]'; exit 0 }
$items = @(Get-CimInstance Win32_Process | ForEach-Object {
      $image = [string]$_.ExecutablePath
      $commandLine = [string]$_.CommandLine
      # A node-hosted CLI runs as node.exe with the entry script on its command
      # line, while a native one runs as its own binary. Accept either, but only
      # when the managed package directory itself is what shows up.
      $matched = $false
      if ($image -and $image.StartsWith($root, [System.StringComparison]::OrdinalIgnoreCase)) { $matched = $true }
      if (-not $matched -and $commandLine -and $commandLine.IndexOf($root, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { $matched = $true }
      if ($matched) {
        [pscustomobject]@{ ProcessId = $_.ProcessId; Name = [string]$_.Name; ExecutablePath = $image }
      }
    })
$items | ConvertTo-Json -Compress

Import-Module -Name 'Microsoft.PowerShell.Utility', 'Microsoft.PowerShell.Management' -ErrorAction SilentlyContinue
$ErrorActionPreference = 'Stop'
$target = [IO.Path]::GetFullPath($env:XINGMANG_TRUST_TARGET)
$root = [IO.Path]::GetFullPath($env:XINGMANG_TRUST_ROOT).TrimEnd("\")
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
$tokenSids = @($identity.User.Value) + @($identity.Groups | ForEach-Object { $_.Value })
$writeMask = [long](2 -bor 4 -bor 16 -bor 64 -bor 256 -bor 65536 -bor 262144 -bor 524288)
$entries = @()
$current = $target
while ($true) {
  $item = Get-Item -LiteralPath $current -Force
  $acl = Microsoft.PowerShell.Security\Get-Acl -LiteralPath $item.FullName
  try { $ownerSid = ([Security.Principal.NTAccount]$acl.Owner).Translate([Security.Principal.SecurityIdentifier]).Value } catch { $ownerSid = [string]$acl.Owner }
  $writeSids = @()
  foreach ($rule in @($acl.Access)) {
    if ([string]$rule.AccessControlType -ne "Allow" -or (([long]$rule.FileSystemRights -band $writeMask) -eq 0)) { continue }
    try { $writeSids += $rule.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value } catch { $writeSids += [string]$rule.IdentityReference }
  }
  $entries += [pscustomobject]@{ ownerSid = $ownerSid; reparsePoint = [bool]($item.Attributes -band [IO.FileAttributes]::ReparsePoint); allowWriteSids = @($writeSids) }
  $normalized = [IO.Path]::GetFullPath($item.FullName).TrimEnd("\")
  if ([StringComparer]::OrdinalIgnoreCase.Equals($normalized, $root)) { break }
  $parent = [IO.Directory]::GetParent($item.FullName)
  if ($null -eq $parent) { throw "Program Files ACL path escaped its root" }
  $current = $parent.FullName
}
[pscustomobject]@{ tokenSids = @($tokenSids); entries = @($entries) } | ConvertTo-Json -Compress -Depth 5

Import-Module -Name 'Microsoft.PowerShell.Utility', 'Microsoft.PowerShell.Management' -ErrorAction SilentlyContinue
$ErrorActionPreference = 'Stop'
$root = [IO.Path]::GetFullPath($env:XINGMANG_TRUST_ROOT)
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
$tokenSids = @($identity.User.Value) + @($identity.Groups | ForEach-Object { $_.Value })
$writeMask = [long](2 -bor 4 -bor 16 -bor 64 -bor 256 -bor 65536 -bor 262144 -bor 524288)
$items = @(Get-Item -LiteralPath $root -Force) + @(Get-ChildItem -LiteralPath $root -Force -Recurse -Depth 2 -Directory)
if ($items.Count -gt 512) { throw "受保护目录树条目数超过上限，拒绝采信: $root" }
$entries = @()
foreach ($item in $items) {
  $acl = Microsoft.PowerShell.Security\Get-Acl -LiteralPath $item.FullName
  try { $ownerSid = ([Security.Principal.NTAccount]$acl.Owner).Translate([Security.Principal.SecurityIdentifier]).Value } catch { $ownerSid = [string]$acl.Owner }
  $writeSids = @()
  foreach ($rule in @($acl.Access)) {
    if ([string]$rule.AccessControlType -ne "Allow" -or (([long]$rule.FileSystemRights -band $writeMask) -eq 0)) { continue }
    try { $writeSids += $rule.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value } catch { $writeSids += [string]$rule.IdentityReference }
  }
  $entries += [pscustomobject]@{ ownerSid = $ownerSid; reparsePoint = [bool]($item.Attributes -band [IO.FileAttributes]::ReparsePoint); allowWriteSids = @($writeSids) }
}
[pscustomobject]@{ tokenSids = @($tokenSids); entries = @($entries) } | ConvertTo-Json -Compress -Depth 5

$ErrorActionPreference = "Stop"
$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
Import-Module -Name 'Microsoft.PowerShell.Utility' -ErrorAction SilentlyContinue
$names = @("HTTP_PROXY","HTTPS_PROXY","ALL_PROXY")
$user = @{}
$machine = @{}
foreach ($name in $names) {
  $value = [Environment]::GetEnvironmentVariable($name, "User")
  if ($value) { $user[$name] = $value }
  $value = [Environment]::GetEnvironmentVariable($name, "Machine")
  if ($value) { $machine[$name] = $value }
}
@{ user = $user; machine = $machine } | ConvertTo-Json -Compress

$ErrorActionPreference = "Stop"
$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
$allowed = @("HTTP_PROXY","HTTPS_PROXY","ALL_PROXY")
$cleared = @()
foreach ($name in ($env:XINGMANG_CLEAR_PROXY -split ";")) {
  if (-not ($allowed -contains $name)) { continue }
  [Environment]::SetEnvironmentVariable($name, $null, "User")
  $cleared += $name
}
"cleared:" + ($cleared -join ";")

$ErrorActionPreference = "Stop"
$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
$allowed = @("ANTHROPIC_BASE_URL","ANTHROPIC_AUTH_TOKEN","ANTHROPIC_API_KEY","CLAUDE_CONFIG_DIR","CLAUDE_CODE_USE_BEDROCK","CLAUDE_CODE_USE_VERTEX","CLAUDE_CODE_USE_FOUNDRY","CLAUDE_CODE_USE_ANTHROPIC_AWS","CLAUDE_CODE_USE_ANTHROPIC_GOOGLE_CLOUD","OPENAI_BASE_URL","OPENAI_API_KEY","CODEX_HOME")
$cleared = @()
$machine = @()
foreach ($name in ($env:XINGMANG_CLEAR_OVERRIDES -split ";")) {
  if (-not ($allowed -contains $name)) { continue }
  if ($null -ne [Environment]::GetEnvironmentVariable($name, "User")) {
    [Environment]::SetEnvironmentVariable($name, $null, "User")
    $cleared += $name
  }
  if ($null -ne [Environment]::GetEnvironmentVariable($name, "Machine")) { $machine += $name }
}
"cleared:" + ($cleared -join ";")
"machine:" + ($machine -join ";")

$ErrorActionPreference = "Stop"
$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
$target = [IO.Path]::GetFullPath($env:XINGMANG_ADD_PATH).TrimEnd("\")
function Test-ListsTarget([string]$value) {
  foreach ($entry in ($value -split ";")) {
    if (-not $entry.Trim()) { continue }
    try {
      $expanded = [Environment]::ExpandEnvironmentVariables($entry.Trim().Trim('"'))
      if ([IO.Path]::GetFullPath($expanded).TrimEnd("\") -ieq $target) { return $true }
    } catch {}
  }
  return $false
}
$machine = [Environment]::GetEnvironmentVariable("Path", "Machine")
$key = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey("Environment")
try {
  $names = $key.GetValueNames()
  $raw = ""
  $kind = [Microsoft.Win32.RegistryValueKind]::ExpandString
  if ($names -contains "Path") {
    $raw = [string]$key.GetValue("Path", "", [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
    if ($key.GetValueKind("Path") -eq [Microsoft.Win32.RegistryValueKind]::String) { $kind = [Microsoft.Win32.RegistryValueKind]::String }
  }
  if ((Test-ListsTarget $machine) -or (Test-ListsTarget $raw)) { "present"; return }
  $next = if ($raw.Trim()) { $raw.TrimEnd(";") + ";" + $target } else { $target }
  $key.SetValue("Path", $next, $kind)
} finally {
  $key.Close()
}
[Environment]::SetEnvironmentVariable("XINGMANG_PATH_REFRESH", $null, "User")
"added"

$ErrorActionPreference = "Stop"
$OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
$target = [IO.Path]::GetFullPath($env:XINGMANG_REMOVE_PATH).TrimEnd("\")
function Test-IsTarget([string]$entry) {
  if (-not $entry.Trim()) { return $false }
  try {
    $expanded = [Environment]::ExpandEnvironmentVariables($entry.Trim().Trim('"'))
    return ([IO.Path]::GetFullPath($expanded).TrimEnd("\") -ieq $target)
  } catch { return $false }
}
$key = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Environment", $true)
if ($null -eq $key) { "absent"; return }
try {
  if (-not ($key.GetValueNames() -contains "Path")) { "absent"; return }
  $raw = [string]$key.GetValue("Path", "", [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
  $kept = @()
  $removed = $false
  foreach ($entry in ($raw -split ";")) {
    if (Test-IsTarget $entry) { $removed = $true } else { $kept += $entry }
  }
  if (-not $removed) { "absent"; return }
  $kind = [Microsoft.Win32.RegistryValueKind]::ExpandString
  if ($key.GetValueKind("Path") -eq [Microsoft.Win32.RegistryValueKind]::String) { $kind = [Microsoft.Win32.RegistryValueKind]::String }
  $key.SetValue("Path", ($kept -join ";"), $kind)
} finally {
  $key.Close()
}
[Environment]::SetEnvironmentVariable("XINGMANG_PATH_REFRESH", $null, "User")
"removed"

$ErrorActionPreference = 'Stop'
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class XingMangTokenElevationProbe {
  [DllImport("advapi32.dll", SetLastError = true)]
  public static extern bool GetTokenInformation(IntPtr token, int informationClass, out int information, int informationLength, out int returnLength);
}
'@
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
$elevationType = 0
$returnLength = 0
$ok = [XingMangTokenElevationProbe]::GetTokenInformation($identity.Token, 18, [ref]$elevationType, 4, [ref]$returnLength)
if (-not $ok) { throw "GetTokenInformation(TokenElevationType) failed: $([Runtime.InteropServices.Marshal]::GetLastWin32Error())" }
switch ($elevationType) {
  1 { "default" }
  2 { "full" }
  3 { "limited" }
  default { throw "Unexpected TokenElevationType: $elevationType" }
}
